using System.Text.Json;
using EqlTracker.Core;
internal static class GearControlsTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool ok,string message="Gear controls assertion failed"){if(!ok)throw new Exception(message);}
        var now=new DateTime(2026,10,18,12,0,0);
        ItemDefinition Item(string key="blade",string[]? slots=null)=>new(){Key=key,Name=key,Classes=["ALL"],Slots=(slots??["PRIMARY","SECONDARY"]).ToList(),MetadataComplete=true,Stats=new(){["STR"]=10}};
        LoadoutProfile Owner(){var owner=new LoadoutProfile{Classes=["WAR"],Level=50};owner.EquipmentPositions=EquipmentPositions.FromEntries([]);foreach(var p in owner.EquipmentPositions)p.Knowledge=EquipmentKnowledge.Empty;return owner;}
        IReadOnlyList<GearPlacementResult> Prepare(LoadoutProfile o,ItemDefinition i,int rank=0,InventoryEntry? e=null,bool theory=false,Catalog? c=null)=>new GearPlacementSession(c??new(){Items=[i]},o,new(){["STR"]=1},EquipmentPositions.For(o,false),EquipmentPositions.For(o,false),theory).Prepare(i,rank,e);
        test("Capture additive migration preserves opt-ins and legacy hours",()=>{var s=new NativeSyncSettings{IntervalHours=4,Login=true,Periodic=false,Verified=true,Key=112};NativeSyncPolicy.Migrate(s);Check(s.IntervalMinutes==240&&s.IntervalHours==4&&s.Login&&!s.Periodic&&s.Verified&&s.Key==112&&s.IntervalChangedAt==null);});
        test("Capture fresh default remains two hours",()=>{var s=new NativeSyncSettings();NativeSyncPolicy.Migrate(s);Check(s.IntervalMinutes==120&&!s.Login&&!s.Periodic);});
        test("Capture custom minutes validate atomically",()=>{var s=new NativeSyncSettings();foreach(int n in new[]{1,5,15,30,60,120,240,1440}){Check(NativeSyncPolicy.SetMinutes(s,n,now));Check(NativeSyncPolicy.Minutes(s)==n);}foreach(int n in new[]{0,-1,1441})Check(!NativeSyncPolicy.SetMinutes(s,n,now)&&s.IntervalMinutes==1440);});
        test("Capture interval changes reschedule one due request without bursts",()=>{var s=new NativeSyncSettings{Verified=true,Key=112,Periodic=true,LastSuccess=now.AddDays(-1)};Check(NativeSyncPolicy.Due(s,now,false));NativeSyncPolicy.SetMinutes(s,15,now);Check(!NativeSyncPolicy.Due(s,now.AddMinutes(14),false)&&NativeSyncPolicy.Due(s,now.AddMinutes(15),false));s.LastSuccess=now.AddMinutes(20);Check(!NativeSyncPolicy.Due(s,now.AddMinutes(34),false));NativeSyncPolicy.SetMinutes(s,15,now.AddMinutes(25));Check(NativeSyncPolicy.NextPeriodic(s)==now.AddMinutes(35));});
        test("Capture login and periodic opt-ins stay independent",()=>{var s=new NativeSyncSettings{Verified=true,Key=112,Login=true};Check(NativeSyncPolicy.Due(s,now,true)&&!NativeSyncPolicy.Due(s,now,false));s.Login=false;s.Periodic=true;Check(NativeSyncPolicy.Due(s,now,false));s.Verified=false;Check(!NativeSyncPolicy.Due(s,now,true));});
        test("Capture existing foreground idle key combat and capture deferrals hold",()=>{Check(NativeSyncPolicy.Eligible(true,5,false,false,false));Check(!NativeSyncPolicy.Eligible(false,5,false,false,false)&&!NativeSyncPolicy.Eligible(true,4.9,false,false,false)&&!NativeSyncPolicy.Eligible(true,5,true,false,false)&&!NativeSyncPolicy.Eligible(true,5,false,true,false)&&!NativeSyncPolicy.Eligible(true,5,false,false,true));});
        test("Capture tooltips distinguish Off Unverified and configured schedules",()=>{var s=new NativeSyncSettings();Check(NativeSyncPolicy.AutoUpdateHelp(s).Contains("Off"));s.Periodic=true;Check(NativeSyncPolicy.AutoUpdateHelp(s).Contains("Unverified"));s.Verified=true;s.Key=112;NativeSyncPolicy.SetMinutes(s,30,now);Check(NativeSyncPolicy.AutoUpdateHelp(s).Contains("30 minutes")&&NativeSyncPolicy.AutoUpdateHelp(s).Contains("3 seconds"));});
        test("Capture minutes survive restart without changing other preferences",()=>{var s=new NativeSyncSettings{IntervalHours=4,Login=true,Periodic=true,Verified=true,Key=112};NativeSyncPolicy.SetMinutes(s,7,now);var copy=JsonSerializer.Deserialize<NativeSyncSettings>(JsonSerializer.Serialize(s))!;Check(copy.IntervalMinutes==7&&copy.IntervalHours==4&&copy.Login&&copy.Periodic&&copy.IntervalChangedAt==now);});
        test("Gear placement shares valid paired Any Slot and explicit invalid results",()=>{var o=Owner();var i=Item(slots:["FINGER"]);var rows=Prepare(o,i);Check(rows.Count(r=>r.Target.Allowed)==4);Check(rows.Single(r=>r.Target.Id=="FINGER:2").Target.Allowed&&rows.Single(r=>r.Target.Id=="CHEST:1").Target.Reason.StartsWith("Does not fit"));});
        test("Gear placement uses supplied preview rank and preserves physical effects",()=>{var o=Owner();var i=Item();var e=new InventoryEntry{Name="blade +4",Augments=[],TransferredOutEffects=["old"]};var row=Prepare(o,i,8,e).Single(r=>r.Target.Id=="PRIMARY:1");Check(row.Entry.Rank==8&&row.Entry.TransferredOutEffects.Single()=="old"&&e.Rank==4);Check(GearPlacementSession.Commit(o,null,row,new(){Items=[i]},out _)&&EquipmentPositions.For(o,false).Single(p=>p.Id=="PRIMARY:1").Item!.Rank==8);Check(GearBuildEditing.Undo(o,null)&&EquipmentPositions.For(o,false).Single(p=>p.Id=="PRIMARY:1").Item==null);});
        test("Gear placement class level and missing metadata are not valid ordinary drops",()=>{var o=Owner();var i=Item();i.Classes=["CLR"];Check(!Prepare(o,i).Any(r=>r.Target.Allowed));i.Classes=["ALL"];i.RequiredLevel=51;Check(!Prepare(o,i).Any(r=>r.Target.Allowed));i.RequiredLevel=0;i.MetadataComplete=false;Check(!Prepare(o,i).Any(r=>r.Target.Allowed));});
        test("Gear placement remains isolated in Theorycraft",()=>{var o=Owner();var i=Item();i.Classes=["CLR"];var c=new Catalog{Items=[i]};var draft=GearBuildEditing.Create(o,"scenario");draft.IsTheorycraft=true;var r=Prepare(o,i,theory:true).Single(r=>r.Target.Id=="PRIMARY:1");Check(r.Target.Allowed&&GearPlacementSession.Commit(o,draft,r,c,out _)&&draft.Positions.Any(p=>p.Item!=null)&&!EquipmentPositions.For(o,false).Any(p=>p.Item!=null));});
        test("Gear placement two-handed conflict displaces Secondary with Undo",()=>{var o=Owner();var two=Item("two",["PRIMARY"]);two.TwoHanded=true;var off=Item("off",["SECONDARY"]);o.EquipmentPositions.Single(p=>p.Id=="SECONDARY:1").Item=new(){Name=off.Name,ConfirmedItemKey=off.Key,Location="Secondary"};var r=Prepare(o,two,c:new(){Items=[two,off]}).Single(r=>r.Target.Id=="PRIMARY:1");Check(GearPlacementSession.Commit(o,null,r,new(){Items=[two,off]},out _));Check(o.EquipmentPositions.Single(p=>p.Id=="SECONDARY:1").Item==null);Check(GearBuildEditing.Undo(o,null)&&o.EquipmentPositions.Single(p=>p.Id=="SECONDARY:1").Item!=null);});
        test("Gear drop revalidation rejects stale Current",()=>{var o=Owner();var i=Item();var r=Prepare(o,i).First(r=>r.Target.Allowed);o.EquipmentPositions[0].Item=new(){Name="changed"};o.EquipmentPositions[0].Knowledge=EquipmentKnowledge.Occupied;Check(!GearPlacementSession.Commit(o,null,r,new(){Items=[i]},out var e)&&e.Contains("changed")&&o.CurrentGearUndo.Count==0);});
        test("Gear placement rejects locked Exaltation without dropping effects",()=>{var o=Owner();var i=Item();var effect=Item("earthshaker");effect.Effects=["Proc: Earthquake"];var c=new Catalog{Items=[i,effect]};var e=new InventoryEntry{Name="blade +4",Augments=[new(){Name="earthshaker",EffectText="Proc: Earthquake"}]};Check(!Prepare(o,i,3,e,c:c).Any(r=>r.Target.Allowed));Check(Prepare(o,i,4,e,c:c).Any(r=>r.Target.Allowed)&&e.Augments.Count==1);});
        test("Gear activation Save creates durable backup and Undo retains it",()=>{var o=Owner();var plan=GearBuildEditing.Create(o,"new");plan.Positions.Single(p=>p.Id=="PRIMARY:1").Item=new(){Name="new +8"};plan.Positions.Single(p=>p.Id=="PRIMARY:1").Knowledge=EquipmentKnowledge.Occupied;string fp=BuildActivation.GearFingerprint(o);Check(BuildActivation.Gear(o,plan,fp,CurrentBackupChoice.Save,"Before",out _));Check(o.GearBuilds.Single(b=>b.Name=="Before").Positions.All(p=>p.Item==null));Check(GearBuildEditing.Undo(o,null)&&o.GearBuilds.Any(b=>b.Name=="Before")&&o.EquipmentPositions.All(p=>p.Item==null));});
        test("Gear activation No Cancel blank name and stale Current are atomic",()=>{var o=Owner();var p=GearBuildEditing.Create(o,"p");string fp=BuildActivation.GearFingerprint(o);Check(!BuildActivation.Gear(o,p,fp,CurrentBackupChoice.Cancel,"x",out _)&&o.GearBuilds.Count==1);Check(!BuildActivation.Gear(o,p,fp,CurrentBackupChoice.Save," ",out _)&&o.CurrentGearUndo.Count==0);Check(!BuildActivation.Gear(o,p,"old",CurrentBackupChoice.Save,"x",out _)&&o.GearBuilds.Count==1);Check(BuildActivation.Gear(o,p,fp,CurrentBackupChoice.Replace,"",out _)&&o.GearBuilds.Count==1);p.IsTheorycraft=true;Check(!BuildActivation.Gear(o,p,BuildActivation.GearFingerprint(o),CurrentBackupChoice.Save,"x",out _)&&o.GearBuilds.Count==1);});
        test("Pet activation backup preserves context and evidence independently",()=>{var o=Owner();var c=new Catalog();var current=PetInventoryEditing.Confirmed(o,c);current.PetType="Earth";current.PetLevel=45;current.SummonSpell="Earth spell";current.Items=[new(){ItemKey="old",Name="old",Position=1,Rank=4,EquipmentVerified=true}];var plan=new PetBuild{Name="new",PetType="Water",PetLevel=50,Items=[new(){ItemKey="new",Name="new",Position=1,Rank=8,EquipmentVerified=true}]};Check(BuildActivation.Pet(o,plan,c,BuildActivation.PetFingerprint(current),CurrentBackupChoice.Save,"Before",out _));var backup=o.PetBuilds.Single(b=>b.Name=="Before");var active=PetInventoryEditing.Confirmed(o,c);Check(backup.PetType=="Earth"&&backup.SummonSpell=="Earth spell"&&backup.Items.Single().EquipmentVerified,"Backup context/evidence: "+JsonSerializer.Serialize(backup));Check(active.PetType=="Water"&&!active.Items.Single().EquipmentVerified,"Active context: "+JsonSerializer.Serialize(active));Check(PetBuildEditing.Undo(active,out _)&&active.Items.Single().Rank==4&&backup.Items.Single().Rank==4,"Undo result: "+JsonSerializer.Serialize(active));});
        test("Pet activation protected exits and stale context create no orphan backup",()=>{var o=Owner();var c=new Catalog();var current=PetInventoryEditing.Confirmed(o,c);var p=new PetBuild{Name="p"};string fp=BuildActivation.PetFingerprint(current);Check(!BuildActivation.Pet(o,p,c,fp,CurrentBackupChoice.Cancel,"x",out _));Check(!BuildActivation.Pet(o,p,c,fp,CurrentBackupChoice.Save," ",out _));current.SummonRank=2;Check(!BuildActivation.Pet(o,p,c,fp,CurrentBackupChoice.Save,"x",out _));p.IsTheorycraft=true;Check(!BuildActivation.Pet(o,p,c,BuildActivation.PetFingerprint(current),CurrentBackupChoice.Replace,"",out _));p.IsTheorycraft=false;p.PetLevel=99;Check(!BuildActivation.Pet(o,p,c,BuildActivation.PetFingerprint(current),CurrentBackupChoice.Save,"x",out _)&&o.PetBuilds.Count==0);});
        test("Pet No replacement and restart retain backup designation and ranks",()=>{var o=Owner();var c=new Catalog();var current=PetInventoryEditing.Confirmed(o,c);var p=new PetBuild{PetType="Earth",Items=[new(){ItemKey="x",Name="x",Rank=7,Position=1}]};Check(BuildActivation.Pet(o,p,c,BuildActivation.PetFingerprint(current),CurrentBackupChoice.Replace,"",out _));var copy=JsonSerializer.Deserialize<LoadoutProfile>(JsonSerializer.Serialize(o))!;Check(PetInventoryEditing.Confirmed(copy,c).Items.Single().Rank==7&&copy.PetBuilds.Count==0);});
        test("Auto Update changes Current only for complete exports when enabled",()=>{var p=new CharacterProfile();var o=p.ActiveLoadout;var named=GearBuildEditing.Create(o,"named");string before=EquipmentPositions.Fingerprint(named.Positions);var snap=new InventorySnapshot{Complete=false,EquipmentPositions=[new(){Id="PRIMARY:1",Slot="Primary",Knowledge=EquipmentKnowledge.Occupied,Item=new(){Name="captured",Location="Primary"}}]};Check(!GearBuildEditing.ApplyExport(p,snap));snap.Complete=true;p.UpdateCurrentBuildFromInventory=false;Check(!GearBuildEditing.ApplyExport(p,snap));p.UpdateCurrentBuildFromInventory=true;Check(GearBuildEditing.ApplyExport(p,snap)&&EquipmentPositions.Fingerprint(named.Positions)==before&&p.NativeSync.Periodic==false);});
        test("Wiki daily startup and manual policies stay distinct",()=>{Check(new CharacterProfile().WikiRefresh==WikiRefreshMode.Daily);Check(WikiRefreshPolicy.Due(WikiRefreshMode.Daily,null,now,true));Check(!WikiRefreshPolicy.Due(WikiRefreshMode.Daily,now.AddHours(-23),now,true));Check(WikiRefreshPolicy.Due(WikiRefreshMode.Daily,now.AddDays(-1),now,false));Check(WikiRefreshPolicy.Due(WikiRefreshMode.Startup,now,now,true)&&!WikiRefreshPolicy.Due(WikiRefreshMode.Startup,null,now,false));Check(!WikiRefreshPolicy.Due(WikiRefreshMode.Manual,null,now,true));});
        test("Wiki refresh preferences survive additive profile persistence",()=>{var p=new CharacterProfile{WikiRefresh=WikiRefreshMode.Manual,LastWikiRefreshAt=now};var copy=JsonSerializer.Deserialize<CharacterProfile>(JsonSerializer.Serialize(p))!;Check(copy.WikiRefresh==WikiRefreshMode.Manual&&copy.LastWikiRefreshAt==now);});
        test("Item changes group resources separately from resists in classic order",()=>{Check(ItemStatGroups.Categories.SequenceEqual(["AC","Resources","Weapons","Stats","Resists"]));Check(ItemStatGroups.Category("HP")=="Resources"&&ItemStatGroups.Category("Mana")=="Resources"&&ItemStatGroups.Category("Vitality")=="Resources"&&ItemStatGroups.Category("ResistMagic")=="Resists"&&ItemStatGroups.Category("STR")=="Stats");Check(ItemStatGroups.Order("STR")<ItemStatGroups.Order("DEX")&&ItemStatGroups.Order("HP")<ItemStatGroups.Order("Mana"));});
    }
}
